/* runtime: neutralize inline margin-left and strip width/height attrs so CSS sizing works reliably */
document.addEventListener('DOMContentLoaded', function () {
    // neutralize inline margin-left:-2px on date bodies
    document.querySelectorAll('#scroll-gallery .dateSection > .row, #infinite-scroll-gallery .dateSection > .row').forEach(function (r) {
        if (r.style && r.style.marginLeft) r.style.marginLeft = '0';
    });

    // remove width/height attributes on the img tags so CSS max-height and auto width take effect.
    document.querySelectorAll('#scroll-gallery img.photo-thumbnail-image, #infinite-scroll-gallery img.photo-thumbnail-image').forEach(function (img) {
        img.removeAttribute('width');
        img.removeAttribute('height');
        // set fallback inline style to avoid FOUC while CSS loads:
        img.style.maxHeight = img.style.maxHeight || '225px';
        img.style.width = img.style.width || 'auto';
        img.style.objectFit = img.style.objectFit || 'cover';
        img.style.display = img.style.display || 'block';
    });

    // inject overlays for .is-video if present
    function createPlaySVG() {
        var svgNS = 'http://www.w3.org/2000/svg';
        var svg = document.createElementNS(svgNS, 'svg');
        svg.setAttribute('viewBox', '0 0 24 24');
        var path = document.createElementNS(svgNS, 'path');
        path.setAttribute('d', 'M8 5v14l11-7z');
        path.setAttribute('fill', '#fff');
        svg.appendChild(path);
        return svg;
    }
    document.querySelectorAll('#scroll-gallery .photo-thumbnail-container.is-video, #infinite-scroll-gallery .photo-thumbnail-container.is-video').forEach(function (container) {
        var anchor = container.querySelector('.mediaLink');
        if (!anchor) return;
        if (anchor.querySelector('.video-overlay-duration')) return; // avoid dupes
        var dur = container.dataset.duration || anchor.dataset.duration || '';
        if (!dur && anchor.dataset.video) {
            try { var parsed = JSON.parse(anchor.dataset.video); if (parsed && parsed.duration) dur = parsed.duration; } catch(e){}
        }
        var badge = document.createElement('div'); badge.className = 'video-overlay-duration'; badge.textContent = dur || '▶';
        anchor.appendChild(badge);
        var playWrap = document.createElement('div'); playWrap.className = 'video-play-badge';
        var circle = document.createElement('div'); circle.className = 'circle'; circle.appendChild(createPlaySVG());
        playWrap.appendChild(circle); anchor.appendChild(playWrap);
    });
});